function push(k, layar) {
  return { tumpukan: [...k.tumpukan, layar] };
}

function pop(k) {
  if (k.tumpukan.length === 1) return k;
  const sisa = k.tumpukan.slice(0, -1);
  return { tumpukan: sisa };
}

function cocok(pola, path) {
  const a = pola.split("/");
  const b = path.split("/");
  if (a.length !== b.length) return null;
  const params = {};
  for (let i = 0; i < a.length; i++) {
    const p = a[i];
    if (p[0] === ":") params[p.slice(1)] = b[i];
    else if (p !== b[i]) return null;
  }
  return params;
}

function reducer(k, aksi) {
  switch (aksi.tipe) {
    case "tambah":
      return { ...k, item: [...k.item, aksi.item] };
    case "hapus": {
      const item = k.item.filter((i) => i.id !== aksi.id);
      return { ...k, item };
    }
    default:
      return k;
  }
}

const antrean = [];
function masuk(a) {
  antrean.push({ ...a, coba: 0 });
}
function gagalKirim(a) {
  a.coba += 1;
  return a.coba >= 3 ? "menyerah" : "ulang";
}

function validasi(f) {
  const galat = {};
  const ok = /^[^@\s]+@[^@\s]+$/;
  if (!ok.test(f.email)) galat.email = "Email tidak valid";
  if (f.sandi.length < 8) galat.sandi = "Minimal 8 karakter";
  return galat;
}

function halaman(data, kursor, ukuran) {
  const mulai = kursor ?? 0;
  const akhir = mulai + ukuran;
  const isi = data.slice(mulai, akhir);
  const berikut = akhir < data.length ? akhir : null;
  return { isi, berikut };
}
